import {TRIALS,TRIAL_RECIPES} from '../content/trials.js?v=0.9.0';
import {DUNGEONS} from '../content/adventures.js?v=0.3.1';
export function renderTrialPanel(name,h,s){if(name!=='trials')return null;const t=h.trials||{},active=s.dungeonRun?.status==='active';return{title:'Зоряні випробування · 40+',html:`<p class="notice">Найкраще проходження: ${t.best||0}/3. Початок — біля вхідного привалу будь-якого з чотирьох данжів. Вся група має бути живою, рівня 40+ і відповідати рівню локації. Вороги підлаштовуються до найвищого рівня групи. Звичайні експедиції залишаються доступними.</p><p>У кожному проходженні чергуються пожирачі відлунь (удари забирають SP) та невтомні (швидші рух і атаки). Зоряні розломи мають попередження 1.8 с. Лікування з усіх джерел послаблене; привал і повернення після загибелі доступні після завершення або поразки групи.</p><div class="reward-grid">${Object.entries(TRIALS).map(([tier,d])=>`<article class="card"><h3>${tier} · ${d.name}</h3><p>HP ворогів ×${d.hp} · сила ×${d.atk} · лікування ${Math.round(d.healing*100)}%.</p><p>+${d.echoes} відлунь, два рецепти; вибір посиленої класової реліквії або ресурсів. ${+tier>=2?'Відкриває зоряну ауру героя.':''}</p><button class="btn" data-trial-start="${tier}" ${!DUNGEONS[s.zone]||h.level<Math.max(40,DUNGEONS[s.zone]?.level||40)||active?'disabled':''}>Почати · західний маршрут</button></article>`).join('')}</div><h3>Рецепти зоряного гарту</h3><p>Виготовлення біля кузні, від рівня 40. Улюблені та запропоновані для передачі матеріали не витрачаються.</p>${Object.entries(TRIAL_RECIPES).map(([id,r])=>`<article class="card"><h3>${r.name}</h3><p>${Object.entries(r.stats).map(([k,v])=>'+'+v+' '+k.toUpperCase()).join(' · ')}. ${r.ore} руди + ${r.shards} жар-уламків + ${r.zeny} Z.</p><button class="btn secondary" data-trial-craft="${id}" ${!t.recipes?'disabled':''}>Виготовити в кузні</button></article>`).join('')}<h3>Зовнішність · зоряна аура</h3><p>Косметична нагорода за складність II або III. Характеристик не додає.</p><button class="btn secondary" data-trial-appearance="toggle" ${!t.appearance?'disabled':''}>${t.equipped?'Прибрати ауру':'Увімкнути ауру'}</button><button class="btn secondary" data-open="dungeon">Звичайні експедиції</button><button class="btn secondary" data-open="rewards">Забрати нагороду</button>`};}
